import{_ as t,o as a,c as o,ag as d}from"./chunks/framework.TQKaXlFR.js";const m=JSON.parse('{"title":"环境要求","description":"","frontmatter":{},"headers":[],"relativePath":"guide/environment.md","filePath":"guide/environment.md"}'),r={name:"guide/environment.md"};function i(n,e,c,s,l,p){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h1><p>本页用于开发者和部署者准备兼容工具链、数据库、缓存与存储。开始前应有自己的代码访问权限和隔离环境；业务功能范围见<a href="./../overview/capabilities.html">能力说明</a>。</p><h2 id="工具链" tabindex="-1">工具链 <a class="header-anchor" href="#工具链" aria-label="Permalink to &quot;工具链&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>当前依据</th><th>核对命令</th></tr></thead><tbody><tr><td>Java</td><td>JDK 17，根 POM 编译 source/target 为 17</td><td><code>java -version</code></td></tr><tr><td>Maven</td><td>推荐 3.9.x；使用 Maven 构建全部模块</td><td><code>mvn -version</code></td></tr><tr><td>Spring Boot</td><td>根 parent 为 3.3.6</td><td>查看根 <code>pom.xml</code></td></tr><tr><td>Node.js</td><td><code>.node-version</code> 20.19.6，engines 至少 20.19.0</td><td><code>node --version</code></td></tr><tr><td>pnpm</td><td>packageManager 固定 10.28.1</td><td><code>pnpm --version</code></td></tr><tr><td>文档引擎</td><td>文档中心使用稳定 VitePress 1.6.4</td><td>查看 <code>apps/docs/package.json</code> 与锁文件</td></tr></tbody></table><p>前端 <code>5.5.9</code> 是派生工作区包版本，不是本项目正式发布 Tag。不要为修复安装错误直接升级 Vite、Vue 或全量依赖。首次可联网安装，之后以 <code>pnpm install --frozen-lockfile</code> 验证清单与锁文件一致；离线安装要求包和元数据已完整缓存。</p><h2 id="数据服务" tabindex="-1">数据服务 <a class="header-anchor" href="#数据服务" aria-label="Permalink to &quot;数据服务&quot;">​</a></h2><p>MySQL 驱动版本为 8.0.33，Flyway 使用 MySQL 支持模块。当前质量候选在 MySQL 8.0.12 实例上验证了包含最新菜单迁移的空库、重启校验和真实业务冒烟。CI 声明 MySQL 5.7/8.0 容器矩阵，但本轮容器矩阵与独立机器未运行；不能把驱动版本或旧验收记录当成对所有数据库版本的支持承诺。</p><p>创建数据库使用 <code>utf8mb4</code> / <code>utf8mb4_general_ci</code>，并检查 URL 的实例、schema、账号和时区。MySQL 与 Redis 建议只对应用所在内网开放，应用账号不需要其他业务 schema 的权限。</p><p>Redis 用于登录态、缓存、验证码、限流以及 Redisson 能力。JWT 签名正确也需要 Redis 中仍有有效登录态；仅启动 MySQL 不够。RedisTemplate 和 Redisson 的连接、数据库编号与认证需要一致，详见<a href="./configuration.html#redis-与-redisson">配置说明</a>。不要共用其他应用的会话数据库后执行清空命令。</p><p>对象存储是可选依赖，默认关闭。验证文件上传/下载需要显式配置已建立的 bucket、服务端可达 endpoint、凭据及对象访问策略。邮件默认关闭；短信、微信和 AI 供应商能力各有配置与外部资格要求，不是空库初始化自动获得的功能。</p><h2 id="操作系统与浏览器" tabindex="-1">操作系统与浏览器 <a class="header-anchor" href="#操作系统与浏览器" aria-label="Permalink to &quot;操作系统与浏览器&quot;">​</a></h2><p>PowerShell 示例针对 PowerShell 7；Bash 示例需要常见 Unix 工具和 OpenSSL。路径从仓库根开始，不依赖某个 IDE 或个人目录。Windows 可直接运行可执行 JAR，不必安装 Docker 才能本地开发；执行 CI 的容器兼容矩阵则需要可用 Linux 容器环境。</p><p>应用面向现代浏览器。开发时先确认 JavaScript、localStorage 和正常同源请求可用；遇到 stale chunk 时按<a href="./../operations/troubleshooting.html">故障排查</a>处理。文档站搜索、字体和静态资源随站点自托管，部署不能只拷贝 Markdown。</p><h2 id="安装成功的判断" tabindex="-1">安装成功的判断 <a class="header-anchor" href="#安装成功的判断" aria-label="Permalink to &quot;安装成功的判断&quot;">​</a></h2><ol><li><code>mvn -version</code> 实际使用 JDK 17，而不是仅系统中安装过它。</li><li>数据库管理员能确认专属库；应用账号可以登录该库。</li><li>Redis 能以配置的密码与 database 编号连接。</li><li>冻结安装成功，前端开发端口没有与其他进程冲突。</li><li>密钥保存在私有配置中；每次重启均使用同一配置主密钥。</li></ol><p>版本不匹配时先修环境，包下载失败时检查当前项目 registry 和网络，不修改全局代理/权限作为默认修复。完整验证步骤见<a href="./verification.html">启动验证</a>。</p><h2 id="源码依据" tabindex="-1">源码依据 <a class="header-anchor" href="#源码依据" aria-label="Permalink to &quot;源码依据&quot;">​</a></h2><p>后端根 <code>pom.xml</code>、<code>common/common-redis/pom.xml</code>、<code>system-admin/pom.xml</code>、<code>system-admin/src/main/resources/application.yml</code>；前端 <code>.node-version</code>、<code>package.json</code>、<code>pnpm-lock.yaml</code>、<code>apps/web-ele/package.json</code>。版本说明与实际验证边界见<a href="./../releases/versions.html">版本组合</a>。</p>',18)])])}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
